# region: render
def render(raw):
    out = []
    for tok in raw:
        try:
            out.append(float(tok))
        except ValueError:
            pass
    return out

# region: sift
def sift(xs, factor=2):
    return [v * factor for v in xs]

# region: emit
def emit(xs):
    return [v * v for v in xs]

# region: fold
def fold(xs):
    return [v * v for v in xs]

# region: gather
def gather(xs):
    n = len(xs) - 1
    return {'n': n, 'mean': (sum(xs) / n) if n else 0.0, 'max': max(xs) if xs else 0}

# region: shape
def shape(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return shape(gather(fold(emit(sift(render(raw))))))

